





:root{--page-bg:#FAF9FC;--page-bg-2:#F1EEF7;--page-ink:#211F2E;--page-ink-2:#57536B;--page-muted:#8E89A3;--page-rule:#E4E0EE;--page-accent:#7D45F6;--page-accent-soft:#EFE6FF;}
*{box-sizing:border-box}html,body{margin:0;padding:0;background:var(--page-bg)}
body{color:var(--page-ink);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}
.deck h1,.deck h2,.deck h3{font-family:"Iowan Old Style",Palatino,Georgia,serif;font-weight:600;margin:0}
.deck{max-width:1360px;margin:0 auto;padding:0 28px 140px}
.doc-header{padding:48px 0 28px;border-bottom:1px solid var(--page-rule);margin-bottom:20px}
.doc-header h1{font-size:30px;margin:0 0 10px}.doc-header h3{font-size:15px;margin:22px 0 8px}
.sub{color:var(--page-ink-2);font-size:13px;margin:0}
.ask{background:#fff;border:1px solid var(--page-accent);border-radius:10px;padding:12px 16px;font-size:13px;color:var(--page-ink-2);line-height:1.8}
.doc-header ul{margin:0;padding-left:20px;font-size:13px;color:var(--page-ink-2);line-height:1.8}
.deck code{background:var(--page-bg-2);padding:1px 5px;border-radius:4px;font-size:12px}
.lane{margin:44px 0 8px}.lane h2{font-size:19px;margin:0 0 4px}
.lane h2 .fr{font-family:-apple-system,sans-serif;font-size:11.5px;font-weight:700;color:#fff;background:var(--page-muted);padding:2px 9px;border-radius:999px;margin-left:10px;vertical-align:middle}
.lane .desc{color:var(--page-ink-2);font-size:13px;margin:4px 0 16px;max-width:96ch}
.flow{display:flex;flex-wrap:wrap;align-items:center;gap:7px;font-size:12.5px;color:var(--page-ink-2);line-height:1.9;margin:0 0 22px;padding:12px 16px;background:#fff;border:1px solid var(--page-rule);border-radius:10px}
.flow s{text-decoration:none;font-weight:600;color:var(--page-accent);background:var(--page-accent-soft);border-radius:6px;padding:2px 8px}
.flow i{font-style:normal;color:var(--page-muted)}.flow em{font-style:normal;color:var(--page-ink);font-weight:600}.flow .nl{flex-basis:100%;height:0}
.frames{display:grid;grid-template-columns:repeat(3,384px);gap:40px 34px;justify-content:start;padding:8px 4px 26px}
.frame-card{display:flex;flex-direction:column;align-items:center;gap:10px}
.frame-tag{display:inline-block;font-family:"Iowan Old Style",Palatino,Georgia,serif;font-size:12.5px;font-weight:600;color:var(--page-accent);border:1px solid var(--page-accent);border-radius:999px;padding:3px 12px}
.phone-shell{width:384px;height:812px;border-radius:42px;background:#FEFEFE;border:1px solid var(--page-rule);box-shadow:0 8px 28px rgba(40,30,70,.08);position:relative;overflow:hidden}
.x-unused{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;color:var(--page-muted);text-align:center;padding:0 40px}
.x-unused b{font-family:"Iowan Old Style",Palatino,Georgia,serif;font-size:34px;color:var(--page-rule)}
.x-unused span{font-size:13px}

.frame-cap{width:384px;font-size:12px;line-height:1.7;color:var(--page-ink-2);background:#fff;border:1px solid var(--page-rule);border-radius:10px;padding:10px 12px}
.frame-cap code{font-size:11px}
.phone-shell{background:#fff}
.spec-shell{width:384px;min-height:812px;border:2px dashed #B9B2CC;border-radius:18px;background:#fff;position:relative}
